    def get_stream(self, aggregate_id: str) -> List[Dict[str, Any]]:
        """
        Retrieves a copy of the immutable event stream for a given aggregate ID.
        """
        with self._lock:
            stream = self._streams.get(aggregate_id, [])
            return [dict(event) for event in stream]
